    "Footer": "\u30d5\u30c3\u30bf\u30fc",
    "Forgot password?": "\u30d1\u30b9\u30ef\u30fc\u30c9\u3092\u304a\u5fd8\u308c\u3067\u3059\u304b\uff1f",
    "Form": "\u30d5\u30a9\u30fc\u30e0",
    "Form field": "\u30d5\u30a9\u30fc\u30e0\u306e\u5165\u529b\u6b04",
